1	// === Types ===
2	type Customer = { yearsWithMHPCO: number };
3	type Item = { type: string; cursed?: boolean; enchantment?: number };
4	type Damage = { itemType: string; amount: number };
5	type Incident = { cause: string; damages: Damage[] };
6	type QuoteStep = { op: "quote"; items: Item[] };
7	type ClaimStep = { op: "claim"; policy: number; incident: Incident };
8	type Step = QuoteStep | ClaimStep;
9	type Scenario = { customer: Customer; steps: Step[] };
10	type Policy = { items: Item[]; remainingCap: number };
11	
12	// === Premium constants ===
13	const PROCESSING_FEE = 5;
14	const FIRST_INSURANCE_RATE = 0.1;
15	const LOYALTY_DISCOUNT_RATE = 0.2;
16	const LOYALTY_YEARS_THRESHOLD = 2;
17	const FOLLOWUP_DISCOUNT_RATE = 0.15;
18	const CURSE_RATE = 0.5;
19	const HIGH_ENCHANTMENT_RATE = 0.3;
20	const HIGH_ENCHANTMENT_THRESHOLD = 5;
21	
22	const BASE_PREMIUMS: Record<string, number> = {
23	  sword: 100,
24	  amulet: 60,
25	  staff: 80,
26	  potion: 40,
27	  rune: 25,
28	  moonstone: 25,
29	};
30	
31	// === Component-block constants ===
32	const BLOCK_SIZE = 3;
33	const COMPONENT_BLOCK_PRICE = 60;
34	const COMPONENT_TYPES = ["rune", "moonstone"];
35	
36	// === Policy / claim constants ===
37	const DEDUCTIBLE = 100;
38	const CAP_MULTIPLIER = 2;
39	const INSURANCE_VALUE_MULTIPLIER = 10;
40	const HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
41	const HALF_REIMBURSEMENT_RATE = 0.5;
42	
43	// === Generic helpers ===
44	const sumBy = <T>(items: T[], selector: (item: T) => number): number =>
45	  items.reduce((sum, item) => sum + selector(item), 0);
46	
47	// === Base premium ===
48	const basePremium = (item: Item): number => {
49	  const price = BASE_PREMIUMS[item.type];
50	  if (price === undefined) throw new Error(`unknown item type: ${item.type}`);
51	  return price;
52	};
53	
54	const isHighlyEnchanted = (item: Item): boolean =>
55	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
56	
57	const itemSurcharge = (item: Item): number => {
58	  const base = basePremium(item);
59	  const curse = item.cursed ? base * CURSE_RATE : 0;
60	  const highEnch = isHighlyEnchanted(item) ? base * HIGH_ENCHANTMENT_RATE : 0;
61	  return curse + highEnch;
62	};
63	
64	const isComponentBlock = (sameTypeItems: Item[]): boolean =>
65	  sameTypeItems.length === BLOCK_SIZE && COMPONENT_TYPES.includes(sameTypeItems[0].type);
66	
67	const groupBasePremium = (sameTypeItems: Item[]): number =>
68	  isComponentBlock(sameTypeItems) ? COMPONENT_BLOCK_PRICE : sumBy(sameTypeItems, basePremium);
69	
70	const groupByType = (items: Item[]): Item[][] => {
71	  const byType = new Map<string, Item[]>();
72	  for (const item of items) {
73	    const bucket = byType.get(item.type) ?? [];
74	    bucket.push(item);
75	    byType.set(item.type, bucket);
76	  }
77	  return [...byType.values()];
78	};
79	
80	const totalBasePremium = (items: Item[]): number =>
81	  sumBy(groupByType(items), groupBasePremium);
82	
83	// === Policy-wide premium modifiers ===
84	const isLoyal = (customer: Customer): boolean =>
85	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
86	
87	const loyaltyDiscount = (base: number, customer: Customer): number =>
88	  isLoyal(customer) ? base * LOYALTY_DISCOUNT_RATE : 0;
89	
90	const firstInsuranceSurcharge = (base: number): number => base * FIRST_INSURANCE_RATE;
91	
92	const followupDiscount = (base: number, isFollowup: boolean): number =>
93	  isFollowup ? base * FOLLOWUP_DISCOUNT_RATE : 0;
94	
95	const premiumForItems = (items: Item[], customer: Customer, isFollowup: boolean): number => {
96	  const base = totalBasePremium(items);
97	  const surcharges = sumBy(items, itemSurcharge) + firstInsuranceSurcharge(base);
98	  const discounts = loyaltyDiscount(base, customer) + followupDiscount(base, isFollowup);
99	  return Math.ceil(base + surcharges - discounts + PROCESSING_FEE);
100	};
101	
102	// === Insurance / cap ===
103	const insuranceValue = (item: Item): number => basePremium(item) * INSURANCE_VALUE_MULTIPLIER;
104	
105	const insuranceSum = (items: Item[]): number => sumBy(items, insuranceValue);
106	
107	const policyCap = (items: Item[]): number => insuranceSum(items) * CAP_MULTIPLIER;
108	
109	// === Claim payout ===
110	const qualifiesForHalfReimbursement = (item: Item): boolean =>
111	  (item.enchantment ?? 0) >= HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD;
112	
113	const reimbursementRate = (item: Item): number =>
114	  qualifiesForHalfReimbursement(item) ? HALF_REIMBURSEMENT_RATE : 1;
115	
116	const applyDeductible = (amount: number): number => Math.max(0, amount - DEDUCTIBLE);
117	
118	const damagePayout = (damage: Damage, items: Item[]): number => {
119	  if (damage.amount < 0) throw new Error(`negative damage amount: ${damage.amount}`);
120	  const item = items.find((i) => i.type === damage.itemType);
121	  if (item === undefined) throw new Error(`uninsured item type: ${damage.itemType}`);
122	  return applyDeductible(damage.amount * reimbursementRate(item));
123	};
124	
125	// === Step handlers ===
126	const handleQuote = (step: QuoteStep, customer: Customer, policies: Policy[]) => {
127	  const premium = premiumForItems(step.items, customer, policies.length > 0);
128	  policies.push({ items: step.items, remainingCap: policyCap(step.items) });
129	  return { premium };
130	};
131	
132	const handleClaim = (step: ClaimStep, policies: Policy[]) => {
133	  const policy = policies[step.policy];
134	  const rawPayout = sumBy(step.incident.damages, (d) => damagePayout(d, policy.items));
135	  const payout = Math.floor(Math.min(rawPayout, policy.remainingCap));
136	  policy.remainingCap -= payout;
137	  return { payout, remainingCap: policy.remainingCap };
138	};
139	
140	export const runScenario = ({ customer, steps }: Scenario): unknown => {
141	  const policies: Policy[] = [];
142	  const results = steps.map((step) =>
143	    step.op === "quote" ? handleQuote(step, customer, policies) : handleClaim(step, policies),
144	  );
145	  return { results };
146	};
