const claimPayout = (damages: Damage[], policy: Policy): number => {
  const rawPayout = sumBy(damages, (d) => damagePayout(d, policy.items));
  return Math.min(Math.floor(rawPayout), policy.remainingCap);
};

const handleClaim = (step: ClaimStep, policies: Policy[]) => {
  const policy = policies[step.policy];
  const payout = claimPayout(step.incident.damages, policy);
  policy.remainingCap -= payout;
  return { payout, remainingCap: policy.remainingCap };
};
